import bpy,os
B=os.path.abspath(os.path.join(os.path.dirname(__file__), '../..'));OUT=os.path.join(B,'seated');names=['Side-reaches','Gentle-turns','Shoulder-rolls','Seated-breathe']
bpy.ops.wm.open_mainfile(filepath=os.path.join(OUT,names[0],'Pip.blend'))
for name in names[1:]:
 with bpy.data.libraries.load(os.path.join(OUT,name,'Pip.blend'),link=False) as (src,dest):dest.scenes=src.scenes
bpy.context.window.scene=bpy.data.scenes['Side-reaches'];guide=bpy.data.texts.new('Pip seated movement guide')
guide.write('''PIP — SEATED MOVEMENT LIBRARY\n\nChoose a movement from the Scene dropdown at the top right. Press Space to play.\n\nSide-reaches: frames 1–300, ten seconds. One hand rests on the knee while the other\narm reaches overhead; Pip bends gently away from the raised arm, then swaps sides.\nGentle-turns: 1–240, eight seconds. Hands on the lap, torso turns each way and returns.\nShoulder-rolls: 1–180, six seconds. Two small slow shoulder circles, then release.\nSeated-breathe: 1–240, eight seconds. Hands move to the belly, slow inhale and exhale,\nthen return to the lap.\n\nAll four clips loop at 30 fps. End frame +1 is the boundary key, not an export frame.\nFeet and chair are fixed. The hips remain at the cushion throughout.\n\nCTRL • placement moves the chair and character together. CTRL • body lean and stretch\ncontrols the trunk and face. Shoulder, elbow, wrist, hip, knee and ankle controls\ndrive smooth limb curves. Mitten objects have keyed transforms. CTRL • eyes and\nexpression has a keyed blink property.\n\nEnable Viewport Overlays → Extras to show the control empties. There are dense editable\nkeys and no external playback handlers. Materials are procedural. The chair is editable\ngeometry in its own collection and is parented under Chair • placement.\n\nThese are new seated performances using the approved Pip mesh. The standing movement\nlibrary remains in the separate animations folder.\n''')
bpy.ops.wm.save_as_mainfile(filepath=os.path.join(OUT,'Pip-seated-movements.blend'),compress=True)
print('SEATED MASTER SAVED',[(s.name,s.frame_end) for s in bpy.data.scenes],flush=True)
